def causal_mask(seq_len):
    # decoder-only / decoder self-attention: token i can only see j <= i
    mask = np.triu(np.ones((seq_len, seq_len)), k=1).astype(bool)
    scores = np.zeros((seq_len, seq_len))
    scores[mask] = -np.inf   # block future positions before softmax
    return scores

def encoder_mask(seq_len):
    # encoder self-attention: fully bidirectional, no masking
    return np.zeros((seq_len, seq_len))

