import numpy as np

def cosine_similarity(a, b):
    return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))

def dot_product(a, b):
    return np.dot(a, b)

def euclidean_distance(a, b):
    return np.linalg.norm(a - b)

# If a and b are unit-normalized (norm == 1),
# cosine_similarity(a, b) == dot_product(a, b),
# and both are monotonically related to euclidean_distance(a, b).

def chunk_by_headers(markdown_text):
    # Structure-aware: split on markdown headers, keep header with its content
    sections = []
    current = []
    for line in markdown_text.split("\n"):
        if line.startswith("#") and current:
            sections.append("\n".join(current))
            current = [line]
        else:
            current.append(line)
    if current:
        sections.append("\n".join(current))
    return sections

def add_overlap(chunks, overlap_sentences=1):
    # Carry the last N sentences of each chunk into the start of the next
    overlapped = []
    for i, chunk in enumerate(chunks):
        prefix = ""
        if i > 0:
            prev_sentences = chunks[i - 1].split(". ")[-overlap_sentences:]
            prefix = ". ".join(prev_sentences) + ". "
        overlapped.append(prefix + chunk)
    return overlapped

def reciprocal_rank_fusion(ranked_lists, k=60):
    # ranked_lists: list of ranked doc-id lists, e.g. [bm25_results, vector_results]
    scores = {}
    for ranked_list in ranked_lists:
        for rank, doc_id in enumerate(ranked_list):
            scores[doc_id] = scores.get(doc_id, 0) + 1 / (rank + k)
    return sorted(scores.items(), key=lambda x: x[1], reverse=True)

