# Online query (naive RAG, no reranking or rewriting)
def naive_rag_query(question, embed_fn, vector_store, llm, k=5):
    query_vector = embed_fn(question)
    top_chunks = vector_store.search(query_vector, k=k)
    context = "\n\n".join(c.metadata["text"] for c in top_chunks)
    prompt = f"Context:\n{context}\n\nQuestion: {question}\nAnswer using only the context above."
    return llm.generate(prompt)

# Simplified agentic RAG loop: the model decides whether to retrieve again
def agentic_rag(question, retrieve_fn, llm, max_steps=3):
    context_so_far = []
    for _ in range(max_steps):
        decision = llm.plan_next_step(question, context_so_far)
        if decision.action == "answer":
            return llm.generate_final_answer(question, context_so_far)
        # decision.action == "retrieve" with a model-generated sub-query
        results = retrieve_fn(decision.query)
        context_so_far.append(results)
    return llm.generate_final_answer(question, context_so_far)

def recall_at_k(eval_set, retrieve_fn, k=5):
    hits = 0
    for item in eval_set:  # item: {question, correct_chunk_id}
        retrieved_ids = [c.id for c in retrieve_fn(item["question"], k=k)]
        hits += int(item["correct_chunk_id"] in retrieved_ids)
    return hits / len(eval_set)

def faithfulness_score(eval_set, generate_fn, judge_llm):
    scores = []
    for item in eval_set:  # item: {question, context, }
        answer = generate_fn(item["question"], item["context"])
        verdict = judge_llm.judge(
            f"Does this answer follow only from the context? "
            f"Context: {item['context']}\nAnswer: {answer}"
        )
        scores.append(verdict.score)
    return sum(scores) / len(scores)

