def orchestrator(task, workers, llm_call):
    plan = llm_call(f"Break this task into sub-tasks: {task}")
    results = []
    for subtask in plan.subtasks:
        worker = workers[subtask.worker_name]
        # Each worker only sees its own scoped subtask, not the full plan
        result = worker.run(subtask.instruction, context=subtask.context)
        results.append(result)
    return llm_call(f"Synthesize a final answer from: {results}")

