JUDGE_PROMPT = """Compare the two summaries of the source text below.
Score each on faithfulness (1-5) and coverage (1-5). Ignore length and formatting.
Source: {source}
Summary A: {a}
Summary B: {b}
Return JSON: {{"faithfulness_a":_, "faithfulness_b":_, "coverage_a":_, "coverage_b":_}}"""

def judge_pair(source, a, b, llm_call):
    forward = llm_call(JUDGE_PROMPT.format(source=source, a=a, b=b))
    reverse = llm_call(JUDGE_PROMPT.format(source=source, a=b, b=a))  # swap to check position bias
    return forward, reverse

def check_groundedness(answer_claims, retrieved_context, judge_call):
    unsupported = []
    for claim in answer_claims:
        prompt = f"Context: {retrieved_context}\nClaim: {claim}\nIs this claim fully supported by the context? Answer yes or no."
        verdict = judge_call(prompt)
        if "no" in verdict.lower():
            unsupported.append(claim)
    return unsupported  # any non-empty result should block or flag the answer

def compare_models(candidate_model, incumbent_model, own_eval_set, score_fn):
    results = {}
    for name, model in [("candidate", candidate_model), ("incumbent", incumbent_model)]:
        scores = [score_fn(model(case["input"]), case["expected"]) for case in own_eval_set]
        results[name] = sum(scores) / len(scores)
    return results  # decision should rest on this, not on public benchmark leaderboards

