import hashlib

def cache_key(prompt, source_version):
    normalized = prompt.strip().lower()
    return hashlib.sha256(f"{normalized}:{source_version}".encode()).hexdigest()

def cached_generate(prompt, source_version, cache, generate_fn, ttl_seconds=3600):
    key = cache_key(prompt, source_version)
    if (cached := cache.get(key)) is not None:
        return cached
    result = generate_fn(prompt)
    cache.set(key, result, ttl=ttl_seconds)
    return result

def stream_with_buffered_moderation(prompt, model_stream, moderator, buffer_sentences=2):
    buffer = ""
    for chunk in model_stream(prompt):
        buffer += chunk
        if buffer.count(".") >= buffer_sentences:
            if moderator.classify(buffer).is_unsafe:
                yield "[response stopped]"
                return
            yield buffer
            buffer = ""
    if buffer and not moderator.classify(buffer).is_unsafe:
        yield buffer

def generate_with_fallback(prompt, primary, secondary, max_retries=2):
    for attempt in range(max_retries):
        try:
            return primary.generate(prompt, timeout=5)
        except (TimeoutError, RateLimitError):
            time.sleep(2 ** attempt)  # exponential backoff
